'use client';

import { useCallback } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ChevronLeftIcon, ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import {
  Pagination,
  PaginationContent,
  PaginationItem,
} from '@/registry/ndeko/ui/pagination';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { AGENT, leadOf, PASS_IDS } from './data';
import { LeadsTable } from './leads-table';
import {
  enrichedCountOf,
  INITIAL,
  LOOP_AFTER_MS,
  pageCountOf,
  pageRowsOf,
  PAGE_SIZE,
  reducer,
  RESTING,
  resultOf,
  SCRIPT,
  TOTAL,
  type LeadsAction,
  type LeadsState,
} from './session';
import { Toolbar } from './toolbar';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function rangeLineOf(page: number, shown: number, total: number) {
  if (total === 0) {
    return 'No lead';
  }
  const offset = page * PAGE_SIZE;
  const first = offset + 1;
  const lastOffset = shown - 1;
  const last = first + lastOffset;
  return `${first} to ${last} of ${total}`;
}

function leadsWordOf(count: number) {
  if (count === 1) {
    return 'lead';
  }
  return 'leads';
}

function passLineOf(state: LeadsState, enriched: number) {
  if (state.litId !== null) {
    const lead = leadOf(state.litId);
    const name = lead?.name ?? 'a lead';
    return `Working on ${name}`;
  }
  if (enriched === 0) {
    return 'Ready to start';
  }
  if (enriched >= PASS_IDS.length) {
    return 'Pass finished';
  }
  return 'Moving to the next lead';
}

export default function AiProduct03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    isFinished,
    restart,
    pressed,
  } = useSession(SESSION);
  useKeptHeight(ref);
  const result = resultOf(state);
  const rows = pageRowsOf(result, state.page);
  const total = result.length;
  const pageCount = pageCountOf(total);
  const pageNumber = state.page + 1;
  const isFirstPage = state.page === 0;
  const isLastPage = pageNumber >= pageCount;
  const rangeLine = rangeLineOf(state.page, rows.length, total);
  const enriched = enrichedCountOf(state);
  const passLine = passLineOf(state, enriched);
  const selectedCount = state.selected.length;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  const focusLater = useCallback(
    (selector: string) => {
      requestAnimationFrame(() => {
        const target = ref.current?.querySelector<HTMLElement>(selector);
        target?.focus();
      });
    },
    [ref]
  );

  /** The button of the empty state leaves with it, so the focus goes back to the search field. */
  function actOnTable(action: LeadsAction) {
    act(action);
    if (action.type === 'filtersCleared') {
      focusLater('[data-leads-search]');
    }
  }

  function clearSelection() {
    act({ type: 'selectionCleared' });
    focusLater('[data-select-page]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-[52rem] w-full @3xl:min-h-[46rem]'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h2 className='text-lg font-semibold text-balance'>Leads</h2>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
                <span className='flex items-baseline gap-1'>
                  <MotionNumber value={total} />
                  {leadsWordOf(total)}
                </span>
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </header>

          <section
            aria-label='Agent pass'
            className='bg-foreground/[0.04] flex flex-wrap items-center gap-x-3 gap-y-1 rounded-lg px-3 py-2'
          >
            <MeshTile
              seed={AGENT.name}
              color={seriesColorOf(AGENT.series)}
              size='md'
            />
            <p className='flex items-baseline gap-1 text-[13px]'>
              {AGENT.name} enriched
              <MotionNumber value={enriched} className='font-medium' />
              of {TOTAL} leads
            </p>
            <span className='text-muted-foreground ms-auto text-xs'>
              <Swap swapKey={passLine}>{passLine}</Swap>
            </span>
          </section>

          <Toolbar
            query={state.query}
            status={state.status}
            owner={state.owner}
            onQuery={(text) => act({ type: 'queryTyped', text })}
            onStatus={(status) => act({ type: 'statusPicked', status })}
            onOwner={(owner) => act({ type: 'ownerPicked', owner })}
          />

          <Fold open={selectedCount > 0}>
            <div className='flex items-center gap-2 text-[13px]'>
              <span className='tabular-nums'>{selectedCount} selected</span>
              <Button
                type='button'
                variant='ghost'
                size='sm'
                onClick={clearSelection}
                className='text-muted-foreground'
              >
                Clear selection
              </Button>
            </div>
          </Fold>

          <div className='bg-card hairline-ring ring-border @container min-h-[26.5rem] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
            <LeadsTable
              rows={rows}
              state={state}
              isActive={isInView}
              pressed={pressed}
              onAction={actOnTable}
            />
          </div>

          <Pagination className='items-center justify-between gap-3'>
            <p className='text-muted-foreground text-xs tabular-nums'>
              {rangeLine}
            </p>
            <PaginationContent>
              <PaginationItem>
                <Button
                  type='button'
                  variant='outline'
                  size='icon-sm'
                  aria-label='Go to the previous page'
                  disabled={isFirstPage}
                  focusableWhenDisabled
                  onClick={() =>
                    act({ type: 'pageTurned', page: state.page - 1 })
                  }
                >
                  <ChevronLeftIcon />
                </Button>
              </PaginationItem>
              <PaginationItem>
                <p className='text-muted-foreground px-1 text-xs tabular-nums'>
                  Page {pageNumber} of {pageCount}
                </p>
              </PaginationItem>
              <PaginationItem>
                <Button
                  type='button'
                  variant='outline'
                  size='icon-sm'
                  aria-label='Go to the next page'
                  disabled={isLastPage}
                  focusableWhenDisabled
                  onClick={() =>
                    act({ type: 'pageTurned', page: state.page + 1 })
                  }
                >
                  <ChevronRightIcon />
                </Button>
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowUpIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/ndeko/ui/table';

import { LandedValue, ShimmerBar } from './cell-states';
import { ownerOf, STATUS_LABEL, type Lead, type LeadStatus } from './data';
import {
  cellKeyOf,
  isLanded,
  type Field,
  type LeadsAction,
  type LeadsState,
  type Sort,
  type SortColumn,
  type SortDirection,
} from './session';

const COLUMN_COUNT = 8;

const STATUS_VARIANT: Record<LeadStatus, 'secondary' | 'info' | 'success'> = {
  new: 'secondary',
  contacted: 'info',
  qualified: 'success',
};

const SORT_BUTTON =
  'group/sort focus-visible:ring-ring/25 hover:bg-foreground/[0.05] hover:text-foreground -mx-1.5 inline-flex h-7 cursor-pointer items-center gap-1 rounded-md px-1.5 transition-[background-color,color,scale] duration-150 outline-none focus-visible:ring-[3px]';

const FRAME_WIDE = 'sticky left-0 w-[100cqw]';

const SORT_LABEL: Record<SortColumn, string> = {
  name: 'Lead',
  company: 'Company',
  status: 'Status',
  size: 'Employees',
};

function ariaSortOf(isSorted: boolean, direction: SortDirection) {
  if (!isSorted) {
    return 'none';
  }
  if (direction === 'asc') {
    return 'ascending';
  }
  return 'descending';
}

function arrowClassOf(isSorted: boolean, direction: SortDirection) {
  if (!isSorted) {
    return 'opacity-0 group-hover/sort:opacity-40 group-focus-visible/sort:opacity-40';
  }
  if (direction === 'asc') {
    return 'opacity-100';
  }
  return 'rotate-180 opacity-100';
}

type SortHeadProps = {
  column: SortColumn;
  sort: Sort | null;
  isFigure?: boolean;
  onSort: (column: SortColumn) => void;
};

function SortHead({ column, sort, isFigure = false, onSort }: SortHeadProps) {
  const isSorted = sort?.column === column;
  const direction = sort?.direction ?? 'asc';

  return (
    <TableHead
      aria-sort={ariaSortOf(isSorted, direction)}
      className={cn(isFigure && 'text-end')}
    >
      <button
        type='button'
        onClick={() => onSort(column)}
        className={cn(SORT_BUTTON, isFigure && 'flex-row-reverse')}
      >
        {SORT_LABEL[column]}
        <ArrowUpIcon
          aria-hidden='true'
          className={cn(
            'size-3.5 transition-[opacity,rotate] duration-200 ease-(--ease-out-strong)',
            arrowClassOf(isSorted, direction)
          )}
        />
      </button>
    </TableHead>
  );
}

type CellPhase = 'empty' | 'fetching' | 'landed';

function phaseOf(state: LeadsState, id: string, field: Field): CellPhase {
  if (isLanded(state, id, field)) {
    return 'landed';
  }
  const filling = state.filling;
  if (filling === null) {
    return 'empty';
  }
  const isThisLead = filling.id === id;
  const isThisField = filling.field === field;
  if (isThisLead && isThisField) {
    return 'fetching';
  }
  return 'empty';
}

type EnrichedCellProps = {
  phase: CellPhase;
  isLanding: boolean;
  isActive: boolean;
  shimmerClassName: string;
  label: string;
  className?: string;
  children: React.ReactNode;
};

function EnrichedCell({
  phase,
  isLanding,
  isActive,
  shimmerClassName,
  label,
  className,
  children,
}: EnrichedCellProps) {
  return (
    <TableCell className={cn('py-0', className)}>
      {phase === 'landed' && (
        <LandedValue isLanding={isLanding}>{children}</LandedValue>
      )}
      {phase === 'fetching' && (
        <>
          <ShimmerBar isActive={isActive} className={shimmerClassName} />
          <span className='sr-only'>Fetching {label}</span>
        </>
      )}
      {phase === 'empty' && (
        <>
          <span aria-hidden='true' className='text-muted-foreground/60'>
            -
          </span>
          <span className='sr-only'>Not enriched yet</span>
        </>
      )}
    </TableCell>
  );
}

function selectedStateOf(isSelected: boolean) {
  if (isSelected) {
    return 'selected';
  }
  return undefined;
}

type LeadRowProps = {
  lead: Lead;
  state: LeadsState;
  isActive: boolean;
  pressed: string | null;
  onAction: (action: LeadsAction) => void;
};

function LeadRow({ lead, state, isActive, pressed, onAction }: LeadRowProps) {
  const owner = ownerOf(lead.owner);
  const isSelected = state.selected.includes(lead.id);
  const isLit = state.litId === lead.id;
  const emailKey = cellKeyOf(lead.id, 'email');
  const sizeKey = cellKeyOf(lead.id, 'size');
  const isSelectPressed = pressed === `select-${lead.id}`;

  return (
    <TableRow
      data-state={selectedStateOf(isSelected)}
      data-lit={isLit}
      className='data-[lit=true]:bg-info/10 h-12'
    >
      <TableCell className='py-0'>
        <Checkbox
          checked={isSelected}
          aria-label={`Select ${lead.name}`}
          onCheckedChange={() => onAction({ type: 'rowToggled', id: lead.id })}
          className={cn(
            'transition-[background-color,box-shadow,scale]',
            pressedQuietOf(isSelectPressed)
          )}
        />
      </TableCell>
      <TableCell className='py-0'>
        <span className='flex items-center gap-2.5 whitespace-nowrap'>
          <Avatar seed={lead.name} className='size-6' />
          <span className='font-medium'>{lead.name}</span>
        </span>
      </TableCell>
      <TableCell className='py-0'>
        <span className='flex items-center gap-2 whitespace-nowrap'>
          <CompanyMark seed={lead.company} />
          {lead.company}
        </span>
      </TableCell>
      <TableCell className='py-0'>
        <Badge variant={STATUS_VARIANT[lead.status]}>
          {STATUS_LABEL[lead.status]}
        </Badge>
      </TableCell>
      <TableCell className='py-0'>
        <span className='flex items-center gap-2 whitespace-nowrap'>
          <Avatar seed={owner.name} className='size-5' />
          {owner.firstName}
        </span>
      </TableCell>
      <TableCell className='text-muted-foreground py-0 whitespace-nowrap'>
        {lead.city}
      </TableCell>
      <EnrichedCell
        phase={phaseOf(state, lead.id, 'email')}
        isLanding={state.settling === emailKey}
        isActive={isActive}
        shimmerClassName='w-40'
        label='the work email'
        className='min-w-56'
      >
        <span className='whitespace-nowrap'>{lead.email}</span>
      </EnrichedCell>
      <EnrichedCell
        phase={phaseOf(state, lead.id, 'size')}
        isLanding={state.settling === sizeKey}
        isActive={isActive}
        shimmerClassName='ms-auto w-8'
        label='the number of employees'
        className='text-end tabular-nums'
      >
        {lead.employees}
      </EnrichedCell>
    </TableRow>
  );
}

type SelectPageBoxProps = {
  rowIds: string[];
  selected: string[];
  onAction: (action: LeadsAction) => void;
};

function SelectPageBox({ rowIds, selected, onAction }: SelectPageBoxProps) {
  const selectedOnPage = rowIds.filter((id) => selected.includes(id));
  const hasRows = rowIds.length > 0;
  const isPageSelected = hasRows && selectedOnPage.length === rowIds.length;
  const isPartlySelected = selectedOnPage.length > 0 && !isPageSelected;

  return (
    <Checkbox
      data-select-page
      checked={isPageSelected}
      indeterminate={isPartlySelected}
      disabled={!hasRows}
      aria-label='Select the leads of this page'
      onCheckedChange={() => onAction({ type: 'pageToggled' })}
    />
  );
}

type LeadsTableProps = {
  rows: Lead[];
  state: LeadsState;
  isActive: boolean;
  pressed: string | null;
  onAction: (action: LeadsAction) => void;
};

export function LeadsTable({
  rows,
  state,
  isActive,
  pressed,
  onAction,
}: LeadsTableProps) {
  const rowIds = rows.map((lead) => lead.id);
  const isEmpty = rows.length === 0;

  function sortBy(column: SortColumn) {
    onAction({ type: 'sorted', column });
  }

  return (
    <Table className='min-w-[56rem]'>
      <caption className='sr-only'>Leads</caption>
      <TableHeader>
        <TableRow className='hover:bg-transparent'>
          <TableHead>
            <SelectPageBox
              rowIds={rowIds}
              selected={state.selected}
              onAction={onAction}
            />
          </TableHead>
          <SortHead column='name' sort={state.sort} onSort={sortBy} />
          <SortHead column='company' sort={state.sort} onSort={sortBy} />
          <SortHead column='status' sort={state.sort} onSort={sortBy} />
          <TableHead>Owner</TableHead>
          <TableHead>City</TableHead>
          <TableHead>Work email</TableHead>
          <SortHead column='size' sort={state.sort} isFigure onSort={sortBy} />
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((lead) => (
          <LeadRow
            key={lead.id}
            lead={lead}
            state={state}
            isActive={isActive}
            pressed={pressed}
            onAction={onAction}
          />
        ))}
        {isEmpty && (
          <TableRow className='hover:bg-transparent'>
            <TableCell colSpan={COLUMN_COUNT} className='p-0'>
              <div
                className={cn(
                  FRAME_WIDE,
                  'flex flex-col items-start gap-3 p-4'
                )}
              >
                <p className='text-muted-foreground text-[13px]'>
                  No lead matches these filters
                </p>
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  onClick={() => onAction({ type: 'filtersCleared' })}
                >
                  Remove the filters
                </Button>
              </div>
            </TableCell>
          </TableRow>
        )}
      </TableBody>
    </Table>
  );
}

'use client';

import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { Input } from '@/registry/ndeko/ui/input';
import { SelectNative } from '@/registry/ndeko/ui/select-native';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { OWNERS, STATUS_LABEL } from './data';
import type { OwnerFilter, StatusFilter } from './session';

const STATUS_SEGMENTS: Segment<StatusFilter>[] = [
  { value: 'all', label: 'All' },
  { value: 'new', label: STATUS_LABEL.new },
  { value: 'contacted', label: STATUS_LABEL.contacted },
  { value: 'qualified', label: STATUS_LABEL.qualified },
];

function ownerFilterOf(value: string): OwnerFilter | null {
  if (value === 'all') {
    return 'all';
  }
  const owner = OWNERS.find((candidate) => candidate.id === value);
  if (owner) {
    return owner.id;
  }
  return null;
}

type ToolbarProps = {
  query: string;
  status: StatusFilter;
  owner: OwnerFilter;
  onQuery: (text: string) => void;
  onStatus: (status: StatusFilter) => void;
  onOwner: (owner: OwnerFilter) => void;
};

export function Toolbar({
  query,
  status,
  owner,
  onQuery,
  onStatus,
  onOwner,
}: ToolbarProps) {
  function pickOwner(event: React.ChangeEvent<HTMLSelectElement>) {
    const picked = ownerFilterOf(event.target.value);
    if (picked) {
      onOwner(picked);
    }
  }

  return (
    <div className='flex flex-wrap items-center gap-2'>
      <div className='relative min-w-44 flex-1'>
        <SearchIcon className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2' />
        <Input
          type='search'
          aria-label='Search leads'
          data-leads-search
          autoComplete='off'
          placeholder='Search name, company or city'
          value={query}
          onChange={(event) => onQuery(event.target.value)}
          className='ps-8'
        />
      </div>
      <Segments
        label='Status'
        value={status}
        segments={STATUS_SEGMENTS}
        onValueChange={onStatus}
      />
      <SelectNative
        aria-label='Owner'
        value={owner}
        onChange={pickOwner}
        className='w-36'
      >
        <option value='all'>All owners</option>
        {OWNERS.map((candidate) => (
          <option key={candidate.id} value={candidate.id}>
            {candidate.name}
          </option>
        ))}
      </SelectNative>
    </div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useEffect, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, FADE } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const SWEEP_MS = 1100;

type ShimmerBarProps = {
  /** False off screen: the band stops where it is. */
  isActive: boolean;
  className?: string;
};

export function ShimmerBar({ isActive, className }: ShimmerBarProps) {
  const bandRef = useRef<HTMLSpanElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    const band = bandRef.current;
    if (!band || shouldReduceMotion || !isActive) {
      return;
    }
    const sweep = [
      { transform: 'translateX(-100%)' },
      { transform: 'translateX(200%)' },
    ];
    const animation = band.animate(sweep, {
      duration: SWEEP_MS,
      iterations: Infinity,
      easing: 'linear',
    });
    return () => animation.cancel();
  }, [isActive, shouldReduceMotion]);

  return (
    <span
      aria-hidden='true'
      className={cn(
        'bg-foreground/[0.07] relative block h-3 overflow-hidden rounded-full',
        className
      )}
    >
      <span
        ref={bandRef}
        className='via-foreground/10 absolute inset-y-0 start-0 w-1/2 bg-linear-to-r from-transparent to-transparent'
      />
    </span>
  );
}

function landingFrom(isLanding: boolean, shouldReduceMotion: boolean) {
  if (!isLanding) {
    return false;
  }
  if (shouldReduceMotion) {
    return { opacity: 0 };
  }
  return { opacity: 0, scale: 1.04 };
}

const SETTLE = { duration: 0.28, ease: EASE_OUT_STRONG };

function landTransitionOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE;
  }
  return SETTLE;
}

type LandedValueProps = {
  /** True for the value that has just arrived: it settles from 1.04. A value that was there already is simply drawn. */
  isLanding: boolean;
  className?: string;
  children: React.ReactNode;
};

export function LandedValue({
  isLanding,
  className,
  children,
}: LandedValueProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const initial = landingFrom(isLanding, shouldReduceMotion);
  const transition = landTransitionOf(shouldReduceMotion);

  return (
    <motion.span
      initial={initial}
      animate={{ opacity: 1, scale: 1 }}
      transition={transition}
      className={cn('inline-block origin-left', className)}
    >
      {children}
    </motion.span>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  AGENT,
  LEADS,
  leadOf,
  PASS_IDS,
  STATUS_ORDER,
  type Lead,
  type LeadStatus,
  type OwnerId,
} from './data';

export type Field = 'email' | 'size';

export type SortColumn = 'name' | 'company' | 'status' | 'size';

export type SortDirection = 'asc' | 'desc';

export type Sort = { column: SortColumn; direction: SortDirection };

export type StatusFilter = 'all' | LeadStatus;

export type OwnerFilter = 'all' | OwnerId;

export type LeadsState = {
  query: string;
  status: StatusFilter;
  owner: OwnerFilter;
  /** Null keeps the order of the list. */
  sort: Sort | null;
  page: number;
  selected: string[];
  litId: string | null;
  filling: { id: string; field: Field } | null;
  /** Cells that hold a value, as `id:field`. */
  landed: string[];
  settling: string | null;
  spoken: string;
};

export type LeadsAction =
  | { type: 'queryTyped'; text: string }
  | { type: 'statusPicked'; status: StatusFilter }
  | { type: 'ownerPicked'; owner: OwnerFilter }
  | { type: 'sorted'; column: SortColumn }
  | { type: 'pageTurned'; page: number }
  | { type: 'rowToggled'; id: string }
  | { type: 'pageToggled' }
  | { type: 'selectionCleared' }
  | { type: 'filtersCleared' }
  | { type: 'leadStarted'; id: string }
  | { type: 'fetching'; id: string; field: Field }
  | { type: 'landed'; id: string; field: Field }
  | { type: 'leadFinished'; id: string };

type Step = SessionStep<LeadsState, LeadsAction>;

export const PAGE_SIZE = 8;

export const TOTAL = LEADS.length;

export const INITIAL: LeadsState = {
  query: '',
  status: 'all',
  owner: 'all',
  sort: null,
  page: 0,
  selected: [],
  litId: null,
  filling: null,
  landed: [],
  settling: null,
  spoken: '',
};

export function cellKeyOf(id: string, field: Field) {
  return `${id}:${field}`;
}

export function isLanded(state: LeadsState, id: string, field: Field) {
  const key = cellKeyOf(id, field);
  return state.landed.includes(key);
}

function isEnriched(state: LeadsState, lead: Lead) {
  const hasEmail = isLanded(state, lead.id, 'email');
  const hasSize = isLanded(state, lead.id, 'size');
  return hasEmail && hasSize;
}

export function enrichedCountOf(state: LeadsState) {
  const enriched = LEADS.filter((lead) => isEnriched(state, lead));
  return enriched.length;
}

function matchesQuery(lead: Lead, query: string) {
  const wanted = query.trim().toLowerCase();
  if (wanted === '') {
    return true;
  }
  const text = `${lead.name} ${lead.company} ${lead.city}`;
  const haystack = text.toLowerCase();
  return haystack.includes(wanted);
}

function matchesStatus(lead: Lead, status: StatusFilter) {
  if (status === 'all') {
    return true;
  }
  return lead.status === status;
}

function matchesOwner(lead: Lead, owner: OwnerFilter) {
  if (owner === 'all') {
    return true;
  }
  return lead.owner === owner;
}

function sizeOf(state: LeadsState, lead: Lead) {
  if (isLanded(state, lead.id, 'size')) {
    return lead.employees;
  }
  return null;
}

/** A size the agent has not found yet sorts after every size, in both directions. */
function compareSizes(
  direction: SortDirection,
  first: number | null,
  second: number | null
) {
  if (first === null && second === null) {
    return 0;
  }
  if (first === null) {
    return 1;
  }
  if (second === null) {
    return -1;
  }
  if (direction === 'asc') {
    return first - second;
  }
  return second - first;
}

function textOrderOf(column: SortColumn, first: Lead, second: Lead) {
  if (column === 'name') {
    return first.name.localeCompare(second.name);
  }
  if (column === 'company') {
    return first.company.localeCompare(second.company);
  }
  return STATUS_ORDER[first.status] - STATUS_ORDER[second.status];
}

function compareLeads(
  state: LeadsState,
  sort: Sort,
  first: Lead,
  second: Lead
) {
  if (sort.column === 'size') {
    const firstSize = sizeOf(state, first);
    const secondSize = sizeOf(state, second);
    return compareSizes(sort.direction, firstSize, secondSize);
  }
  const order = textOrderOf(sort.column, first, second);
  if (sort.direction === 'asc') {
    return order;
  }
  return -order;
}

export function resultOf(state: LeadsState) {
  const kept = LEADS.filter((lead) => {
    const fitsQuery = matchesQuery(lead, state.query);
    const fitsStatus = matchesStatus(lead, state.status);
    const fitsOwner = matchesOwner(lead, state.owner);
    return fitsQuery && fitsStatus && fitsOwner;
  });
  const sort = state.sort;
  if (sort === null) {
    return kept;
  }
  return [...kept].sort((first, second) =>
    compareLeads(state, sort, first, second)
  );
}

export function pageCountOf(total: number) {
  const pages = Math.ceil(total / PAGE_SIZE);
  return Math.max(1, pages);
}

export function pageRowsOf(rows: Lead[], page: number) {
  const start = page * PAGE_SIZE;
  const end = start + PAGE_SIZE;
  return rows.slice(start, end);
}

function withFilters(state: LeadsState, changes: Partial<LeadsState>) {
  return { ...state, ...changes, page: 0 };
}

function sorted(state: LeadsState, column: SortColumn): LeadsState {
  const current = state.sort;
  if (current === null || current.column !== column) {
    return { ...state, sort: { column, direction: 'asc' }, page: 0 };
  }
  if (current.direction === 'asc') {
    return { ...state, sort: { column, direction: 'desc' }, page: 0 };
  }
  return { ...state, sort: null, page: 0 };
}

function rowToggled(state: LeadsState, id: string): LeadsState {
  if (state.selected.includes(id)) {
    const rest = state.selected.filter((selectedId) => selectedId !== id);
    return { ...state, selected: rest };
  }
  return { ...state, selected: [...state.selected, id] };
}

function pageToggled(state: LeadsState): LeadsState {
  const rows = pageRowsOf(resultOf(state), state.page);
  const ids = rows.map((lead) => lead.id);
  const isAllSelected = ids.every((id) => state.selected.includes(id));
  if (isAllSelected) {
    const rest = state.selected.filter((id) => !ids.includes(id));
    return { ...state, selected: rest };
  }
  const added = ids.filter((id) => !state.selected.includes(id));
  return { ...state, selected: [...state.selected, ...added] };
}

function landed(state: LeadsState, id: string, field: Field): LeadsState {
  const key = cellKeyOf(id, field);
  return {
    ...state,
    filling: null,
    landed: [...state.landed, key],
    settling: key,
  };
}

function leadFinished(state: LeadsState, id: string): LeadsState {
  const lead = leadOf(id);
  const name = lead?.name ?? id;
  const count = enrichedCountOf(state);
  const spoken = `${AGENT.name} enriched ${name}: ${count} of ${TOTAL} leads`;
  return { ...state, litId: null, spoken };
}

export function reducer(state: LeadsState, action: LeadsAction): LeadsState {
  switch (action.type) {
    case 'queryTyped':
      return withFilters(state, { query: action.text });
    case 'statusPicked':
      return withFilters(state, { status: action.status });
    case 'ownerPicked':
      return withFilters(state, { owner: action.owner });
    case 'sorted':
      return sorted(state, action.column);
    case 'pageTurned':
      return { ...state, page: action.page };
    case 'rowToggled':
      return rowToggled(state, action.id);
    case 'pageToggled':
      return pageToggled(state);
    case 'selectionCleared':
      return { ...state, selected: [] };
    case 'filtersCleared':
      return withFilters(state, { query: '', status: 'all', owner: 'all' });
    case 'leadStarted':
      return { ...state, litId: action.id, settling: null };
    case 'fetching':
      return { ...state, filling: { id: action.id, field: action.field } };
    case 'landed':
      return landed(state, action.id, action.field);
    case 'leadFinished':
      return leadFinished(state, action.id);
  }
}

function leadSteps(id: string): Step[] {
  return [
    { after: 400, action: { type: 'leadStarted', id } },
    { after: 250, action: { type: 'fetching', id, field: 'email' } },
    { after: 850, action: { type: 'landed', id, field: 'email' } },
    { after: 200, action: { type: 'fetching', id, field: 'size' } },
    { after: 700, action: { type: 'landed', id, field: 'size' } },
    { after: 350, action: { type: 'leadFinished', id } },
  ];
}

/** The agent works on its own, so the pass goes on after a person takes over the table. */
export const SCRIPT: Step[] = PASS_IDS.flatMap((id) => leadSteps(id));

function endOf(script: Step[]) {
  let state = INITIAL;
  for (const step of script) {
    state = reducer(state, step.action);
  }
  return state;
}

export const RESTING: LeadsState = { ...endOf(SCRIPT), settling: null };

